{"implementation": "def solve(case):
    threshold = case.get('threshold')
    if threshold is None or not isinstance(threshold, (int, float)):
        raise ValueError('Invalid threshold')
    calls = case.get('calls')
    if not isinstance(calls, list):
        raise ValueError('Invalid calls')
    accepted_ids = []
    diagnostics = []
    for call in calls:
        if not isinstance(call, dict):
            raise ValueError('Invalid call')
        call_id = call.get('call_id')
        loss_without = call.get('loss_without_call')
        loss_with = call.get('loss_with_call')
        pred_tokens = call.get('prediction_tokens')
        parseable = call.get('parseable')
        if any(x is None for x in [call_id, loss_without, loss_with, pred_tokens, parseable]):
            raise ValueError('Missing field in call')
        if not isinstance(loss_without, (int, float)) or not isinstance(loss_with, (int, float)):
            raise ValueError('loss fields must be numbers')
        if not isinstance(pred_tokens, int) or pred_tokens <= 0:
            raise ValueError('prediction_tokens must be positive integer')
        if not isinstance(parseable, bool):
            raise ValueError('parseable must be bool')
        gain = loss_without - loss_with
        normalized_gain = gain / pred_tokens
        accepted = parseable and normalized_gain >= threshold
        diagnostics.append({
            'accepted': accepted,
            'call_id': call_id,
            'normalized_gain': normalized_gain
        })
        if accepted:
            accepted_ids.append(call_id)
    return {
        'accepted_call_ids': accepted_ids,
        'diagnostics': diagnostics
    }"}
